package com.medicore.inventory.service;
import com.medicore.inventory.dto.*; import com.medicore.inventory.entity.InventoryItem; import com.medicore.inventory.exception.InsufficientStockException; import com.medicore.inventory.repository.InventoryRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class InventoryService {private final InventoryRepository repository; public InventoryService(InventoryRepository repository){this.repository=repository;} @Transactional public InventoryResponse adjust(Long id,int quantity){if(quantity<0)throw new IllegalArgumentException("Quantity must be nonnegative");InventoryItem item=repository.findByMedicineId(id).orElseGet(()->new InventoryItem(id,0));item.setQuantity(quantity);return response(repository.save(item),false);} @Transactional public InventoryResponse reserve(Long id,int quantity){if(quantity<1)throw new IllegalArgumentException("Quantity must be positive");InventoryItem item=repository.findForUpdate(id).orElseThrow(()->new IllegalArgumentException("Inventory not found"));if(item.getQuantity()<quantity)throw new InsufficientStockException();item.setQuantity(item.getQuantity()-quantity);return response(repository.save(item),true);} @Transactional public InventoryResponse release(Long id,int quantity){if(quantity<1)throw new IllegalArgumentException("Quantity must be positive");InventoryItem item=repository.findForUpdate(id).orElseThrow(()->new IllegalArgumentException("Inventory not found"));item.setQuantity(item.getQuantity()+quantity);return response(repository.save(item),false);} private InventoryResponse response(InventoryItem i,boolean reserved){return new InventoryResponse(i.getMedicineId(),i.getQuantity(),reserved);}}
